  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES contains EUR, USD, GBP', () => {
  assert.ok(RATES.EUR !== undefined);
  assert.ok(RATES.USD !== undefined);
  assert.ok(RATES.GBP !== undefined);
  assert.equal(RATES.EUR, 1);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(12345, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('convert EUR to USD uses rate', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, roundCents(10000 * 1.085));
});

test('convert EUR to GBP uses rate', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, roundCents(10000 * 0.8425));
});

test('convert returns UNKNOWN_CURRENCY for invalid currency', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert returns integer cents', () => {
  const result = convert(12345, 'USD');
  assert.equal(Number.isInteger(result.value), true);
});

test('convert rounds correctly', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(Number.isInteger(result.value), true);
});

test('formatMoney EUR shows euro sign', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD shows dollar sign', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP shows pound sign', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney formats with thousands separators', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
});

test('formatMoney handles small amounts', () => {
  assert.equal(formatMoney(5, 'EUR'), '€0.05');
  assert.equal(formatMoney(5, 'USD'), '$0.05');
});

test('formatMoney handles negative amounts', () => {
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
});

test('formatMoney handles zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney handles large amounts', () => {
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
});

test('formatMoney uses unknown currency code if not recognized', () => {
  assert.equal(formatMoney(123456, 'XYZ'), 'XYZ1,234.56');
});

test('convert chain EUR -> USD -> GBP', () => {
  const eur = 10000;
  const usd = convert(eur, 'USD');
  assert.equal(usd.ok, true);
  const gbp = convert(usd.value / 1.085 * 1.085, 'GBP');
  assert.equal(gbp.ok, true);
});

